def busca_binaria(arr, low, high, alvo):
    if low > high:
        return -1
    mid = (low + high) // 2
    if arr[mid] == alvo:
        return mid
    elif arr[mid] > alvo:
        return busca_binaria(arr, low, mid - 1, alvo)
    else:
        return busca_binaria(arr, mid + 1, high, alvo)

